def _vcgc_face():
    """受治理家族從哪來——**委派給 VCGC,不自己再寫一把尺**(L30 一個出處)。

    批698 的「委派不是複製」推到這裡:哪些檔算受治理,答案只有 CGC_MDL149 一個出處;
    格子只問它、不自己數。它缺席就誠實回 None,不是回一個自己猜的數。
    """
    try:
        import importlib.util as _ilu
        hits = sorted((HERE).glob("CGC_MDL149_VeritasCentralGovernanceConsole_v*.py"))
        if not hits:
            return None
        sp = _ilu.spec_from_file_location("_grid_vcgc", hits[-1])
        m = _ilu.module_from_spec(sp)
        sp.loader.exec_module(m)
        return m._tail_files()
    except Exception:
        return None


def _probe_kind(text: str) -> str:
    """批706:**委派給 CGC_MDL147**(它是煙測閘,「誰有真自測」本來就是它的判斷)。

    批705 我把 AST 判準寫在格子裡,MDL147 裡另有一份字面判準——**同一個問題兩個出處**(L30)。
    批706 把判準收進 MDL147 並收緊成 AST,這裡改成問它;問不到才退回本地副本,
    並且**退回時要講**(不是靜靜地用一把可能不一樣的尺)。
    """
    try:
        import importlib.util as _ilu
        _h = sorted(HERE.glob("CGC_MDL147_EngineSmokeGate_v*.py"))
        if _h:
            _sp = _ilu.spec_from_file_location("_grid_smoke", _h[-1])
            _m = _ilu.module_from_spec(_sp)
            _sp.loader.exec_module(_m)
            return _m.probe_kind(text)
    except Exception:
        pass
    return _probe_kind_local(text)


def _probe_kind_local(text: str) -> str:
    """這支到底有沒有一個**跑得動的** `--selftest`,用 AST 判,不看字面。

    批705 自審:批704 分類 118 支無站家族時,判準是 `"--selftest" in text`。
    那把尺吃到了**散文** —— 用法說明裡的一行字、argparse 的錯誤訊息,
    於是 `SUP_MDL143_PackEngine` 和兩支 pytest 檔被算成「有自測卻沒上站」,
    **一批 33 支裡誤判 3 支**。字面比對分不出「這支支援這個旗標」和「這支提到這個旗標」。

    AST 層只認兩種真的會生效的寫法:
        add_argument("--selftest", ...)              argparse 真的收這個旗標
        "--selftest" in argv / argv[1] == "--selftest"   手寫解析真的比對它
    實測校準:拿 33 支**真的跑過一遍**的結果對答案,32/33 一致。
    唯一不一致的是 `CGC_MDL052_EnvmgrRouter` —— 它是**路由器**,
    把 `--selftest` 當 dict 的值轉給別的引擎,算不算「有自測」本來就是模糊的;
    它已經上站了,所以這一項不影響 PENDING 的判讀。**殘留說出來,不四捨五入。**
    """
    try:
        tree = ast.parse(text)
    except SyntaxError:
        return "UNPARSED"
    flag = False
    for n in ast.walk(tree):
        if isinstance(n, ast.Call):
            nm = getattr(n.func, "attr", None) or getattr(n.func, "id", None)
            if nm == "add_argument" and any(isinstance(a, ast.Constant)
                                            and a.value == "--selftest" for a in n.args):
                flag = True
        if isinstance(n, ast.Compare):
            sides = [n.left] + list(n.comparators)
            if any(isinstance(x, ast.Constant) and x.value == "--selftest" for x in sides) \
                    and any(isinstance(o, (ast.In, ast.Eq)) for o in n.ops):
                flag = True
    if flag:
        return "SELFTEST"
    has_main = any(isinstance(n, ast.If) and isinstance(n.test, ast.Compare)
                   and isinstance(n.test.left, ast.Name) and n.test.left.id == "__name__"
                   for n in ast.walk(tree))
    return "MAIN_ONLY" if has_main else "MODULE"


def station_coverage(exempt=None, stations=None) -> dict:
    """受治理的家族,有沒有人在看?三態:

        STATIONED  格子上有至少一站站在它上面
        EXEMPT     不必有站——**逐條具名且寫得出為什麼**
        PENDING    受治理、沒有站、也沒有具名豁免 —— **這一欄就是還沒人看的**

    批704:格子報「290 綠」的時候,分母是 294 站;而 294 站只蓋住 246/364 個受治理家族。
    沒有站的家族不會變紅——它只是不存在於冊上。覆蓋率不被量,綠就只是綠了看得到的那些。
    """
    face = _vcgc_face()
    if not face:
        return {"state": "NODATA", "why": "CGC_MDL149 缺席或載入失敗:受治理面問不到,不自己猜"}
    exempt = STATION_EXEMPT if exempt is None else exempt

    def fam(x):
        return re.sub(r"_v\d{1,4}\.py$", "", Path(str(x)).name).removesuffix(".py")

    sta = {fam(s["path"]) for s in (battery(False) if stations is None else stations) if s.get("path")}
    rows = []
    for _k, q in face.items():
        f = fam(q)
        if f == _SELF_FAMILY:
            continue                      # LL133:自己不進分母
        hit = next((w for frag, w in exempt if frag and frag in str(q)), None)
        if f in sta:
            rows.append({"family": f, "state": "STATIONED", "why": ""})
        elif hit:
            rows.append({"family": f, "state": "EXEMPT", "why": hit})
        else:
            try:
                _k = _probe_kind(Path(q).read_text(encoding="utf-8", errors="replace"))
            except Exception:
                _k = "UNREADABLE"
            # 批705:PENDING 不只是一個數字——附上「它現在跑得動什麼」,
            #   下一批才知道從哪一支開始(SELFTEST = 掛上去就有燈;MAIN_ONLY = 要先寫檢)。
            rows.append({"family": f, "state": "PENDING", "why": "", "probe": _k,
                         "path": str(q).split("VeritasIntelligenceAnalytics/")[-1]})
    t = {k: [r for r in rows if r["state"] == k] for k in ("STATIONED", "EXEMPT", "PENDING")}
    _pk = {}
    for r in t["PENDING"]:
        _pk[r.get("probe", "?")] = _pk.get(r.get("probe", "?"), 0) + 1
    return {"state": "OK", "n": len(rows), "tally": {k: len(v) for k, v in t.items()},
            "pending_kind": _pk, "rows": rows, "pending": t["PENDING"],
            "pct": round(len(t["STATIONED"]) / max(1, len(rows)) * 100, 1)}


