# ===== 批423:不卡斷三件套(操作員令「卡斷 加入20個加速器 不卡斷 動態進度條」)=====
# 根因(工作站實錄):via-go 卡在「── ① TEST(自測矩陣)──」不動。
# 格子這一端其實一直在印(逐站 flush),真正吞掉輸出的是 AllGreen v0100 的
#   $out = & $PY @Argv 2>&1 | Out-String       ← 緩衝到子行程結束才吐
# 200 站序列等於整段畫面空白 = 看起來就是死機。批419e 同一個病的 PowerShell 版:
# **捕捉到卻不顯示,等於沒捕捉。**
# 這一批在格子側補三件,讓「還活著」這件事在任何管道都看得見:
#   ①動態進度條(TTY 走 \r 就地重畫;非 TTY 走節流換行,不洗版)
#   ②PROGRESS.json 心跳(每站落檔=外部 via-bg / AllGreen 可證明它在動)
#   ③Ctrl+C 安全落檔(中斷不是崩潰:寫出已完成的部分證據,誠實回 rc=130)
_TTY = bool(getattr(sys.stdout, "isatty", lambda: False)())
# 心跳檔名**刻意不叫 GRID_***:既有消費者都用 sorted(OUT.glob("GRID_*.json"))[-1]
# 或按 mtime 取「最新證據」——VRN_ENG068_DailyBrief(三版)、CGC_MDL131_ProjectCompletion
# (按 mtime,而心跳永遠最後寫=必中)、CGC_MDL095_DeckServer、Invoke-VIA-FinishLine。
# 叫 GRID_PROGRESS.json 會讓它們把心跳當成證據檔讀(字母序 GRID_P > GRID_2)。
# 教訓:新增產出檔之前先查誰在 glob 同一個樣式。
PROG_P = OUT / "SELFTEST_PROGRESS.json"


def accel_lamp() -> str:
    """20 加速器真點名(SUP_MDL737 → Celeritas)。缺席=誠實說缺,不點假燈。"""
    try:
        sys.path.insert(0, str(VIA / "supportive modules"))
        import importlib
        _m = importlib.import_module("SUP_MDL737_SuperAccelModule_v0104")
    except Exception:
        try:
            hits = sorted((VIA / "supportive modules").glob("SUP_MDL737_SuperAccelModule_v*.py"))
            if not hits:
                return "加速器:SUP_MDL737 缺檔(誠實;不影響跑,只是沒加速)"
            import importlib.util
            spec = importlib.util.spec_from_file_location("via_accel_dyn", hits[-1])
            _m = importlib.util.module_from_spec(spec)
            sys.modules[spec.name] = _m
            spec.loader.exec_module(_m)
        except Exception as exc:
            return f"加速器:載入失敗 {type(exc).__name__}(誠實;不影響跑)"
    try:
        a = _m.activate(apply_limits=True)
    except Exception as exc:
        return f"加速器:activate 例外 {type(exc).__name__}(誠實)"
    if not a.get("celeritas"):
        return f"加速器:Celeritas 未載入 — {a.get('err') or '無因由'}(誠實;退無加速)"
    return (f"加速器:Celeritas OK · lib {a['libs_available']}/{a['libs_total']}"
            f" · 能力 {a['capability_real']}/{a['capability_total']}"
            f" · 執行緒預算 {a.get('thread_budget')} · 模式 {a.get('mode')}"
            + (f" · 缺 {len(a['missing'])} 支(列名不假在)" if a.get("missing") else ""))


def _bar(done, total, t0, ok, fail, skip, cur="", width=26) -> None:
    """動態進度條。TTY 就地重畫;非 TTY(被 AllGreen 導向檔案)節流換行印,
    否則 200 行進度條會把真正的站名洗掉。"""
    frac = done / max(1, total)
    el = time.time() - t0
    eta = int(el / done * (total - done)) if done else 0
    s = (f"  [{'█' * int(width * frac)}{'░' * (width - int(width * frac))}]"
         f" {done}/{total} {frac * 100:4.1f}% · 經過 {int(el)}s · 剩約 {eta}s"
         f" · OK {ok} FAIL {fail} SKIP {skip}")
    if _TTY:
        print("\r" + s + " " * 8, end="", flush=True)
    elif done == total or done % 10 == 0:      # 非 TTY:每 10 站一行=看得到在動又不洗版
        print(s + (f" · 正在 {cur[:40]}" if cur else ""), flush=True)


def _progress_write(done, total, t0, ok, fail, skip, cur="", state="RUNNING") -> None:
    """心跳落檔。外部(via-bg / AllGreen 輪詢)靠它證明行程還活著,
    不必去猜『沒輸出』是卡死還是在跑。"""
    try:
        OUT.mkdir(parents=True, exist_ok=True)
        PROG_P.write_text(json.dumps({
            "schema": "VIA.SelftestGrid.progress.v1", "state": state,
            "done": done, "total": total, "ok": ok, "fail": fail, "skip": skip,
            "elapsed_s": round(time.time() - t0, 1),
            "eta_s": int((time.time() - t0) / done * (total - done)) if done else None,
            "current": cur, "pid": os.getpid(),
            "heartbeat": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        }, ensure_ascii=False, indent=1), encoding="utf-8")
    except Exception:
        pass                                    # 心跳失敗不得拖垮主流程(批419d 教訓)


# ═══ 批616:逾時律 ══════════════════════════════════════════════════════════
# 工作站實錄(批616 貼回):252 站跑 4,394s 還沒完,而畫面上一整排紅其實是**逾時**——
#   中央治理台 600s · 介面合約 600s · 引擎調度匯流排 600s · 族群回測 600s ·
#   族群分類×價格指數 900s · 產品資格閘 900s · 轉檔器 DPI 600s · 首頁文字擷取 180s …
# 兩件事一起錯:
#   ① **逾時被算成 FAIL**。我自己在批611 的站名上寫「被砍的站等於沒跑過,不是紅」,
#      格子本身卻還在 `return {"state": "FAIL", "rc": "TIMEOUT"}`。
#      逾時的站**沒有結論**:它可能是綠的、也可能是紅的,我們不知道。
#      算成紅就是**編造了一個我們沒量到的結論**,而且會把真紅淹在裡面。
#   ② **逾時秒數是照容器調的**。容器 31s 的站在工作站要 164s;
#      同一個數字在兩台機器上是兩種意思。
# 所以:TIMEOUT 獨立成態(不算紅也不算綠),而且逾時**跟著機器走**。
CALIB_BASELINE_SEC = 0.024   # 容器 py3.11 實測中位數(批616;純迴圈 300k + 一次子行程啟動)
_CALIB = {"factor": None, "why": ""}


def machine_factor() -> tuple:
    """量這台機器比基準慢幾倍。固定工作量,取三次中位數。
    夾在 [1.0, 8.0]:**永不縮短**宣告的逾時(只增不減),也不讓離群值把上限炸掉。
    `VIA_GRID_TIME_FACTOR` 可由操作員直接指定(他的手優先於我的量測)。"""
    if _CALIB["factor"] is not None:
        return _CALIB["factor"], _CALIB["why"]
    env = os.environ.get("VIA_GRID_TIME_FACTOR", "").strip()
    if env:
        try:
            f = max(1.0, min(8.0, float(env)))
            _CALIB.update(factor=f, why=f"操作員指定 VIA_GRID_TIME_FACTOR={env}")
            return f, _CALIB["why"]
        except Exception:
            pass
    xs = []
    for _ in range(3):
        t0 = time.perf_counter()
        acc = 0
        for i in range(300000):
            acc += i * i % 7
        try:
            subprocess.run([sys.executable, "-c", "pass"], capture_output=True, timeout=60)
        except Exception:
            pass
        xs.append(time.perf_counter() - t0)
    med = sorted(xs)[1]
    f = max(1.0, min(8.0, med / CALIB_BASELINE_SEC))
    _CALIB.update(factor=round(f, 2),
                  why=f"校準 {med:.3f}s / 容器基準 {CALIB_BASELINE_SEC:.3f}s → ×{f:.2f}")
    return _CALIB["factor"], _CALIB["why"]


def scaled_timeout(sec: int) -> int:
    f, _ = machine_factor()
    return int(round(sec * f))


# ── 批700:態→記號的**唯一一張表**。原本是三處字面 dict,只寫了 OK/FAIL/SKIP ──
#   而 run_one 明明生得出 TIMEOUT(2921 行)、main 生得出 NOT_RUN(中斷)。實跑量到的後果有兩面:
#     加速器在位(accel_map):KeyError 被工人吞掉 —— 那一站的行**從頭到尾不印**,
#       進度條與心跳跳過它。總結還是對的,可是跑的當下你看不到那一站,
#       而逾時的那一站正是你最需要看到的一站(批423 立心跳就是為了這個場景)。
#     加速器缺席(ThreadPoolExecutor 退路):**整跑當場炸 KeyError: 'TIMEOUT'**,293 站全丟。
#   所以這張表:① 只有一份 ② 蓋住引擎生得出的每一態 ③ **永不丟例外** ——
#   沒見過的態要大聲現形(印 `?態`),不可以讓它安安靜靜消失,也不可以讓它殺掉整跑。
MARKS = {"OK": "OK  ", "FAIL": "FAIL", "SKIP": "SKIP",
         "TIMEOUT": "TIME", "NOT_RUN": "NRUN", "LOCKED": "LOCK"}


def _mark(state) -> str:
    return MARKS.get(state, f"?{str(state)[:3]}")


# ── 批700:鎖撞不是紅燈。DuckDB 是單寫者,庫被別人佔著時這一跑**量不到**,不是引擎壞了 ──
#   判準刻意寫窄:要同時有 DuckDB 那句鎖訊息**和**一個 .duckdb 檔名。
#   寬一點(例如只看到 "lock" 或只看到 "duckdb")就會變成一道洗紅成綠的後門,
#   那比假紅更糟 —— 假紅會被人去查,假綠不會。
_LOCK_PHRASE = "Could not set lock on file"
_LOCK_DB = re.compile(r'([^"\s/\\]+\.duckdb)')
_LOCK_PID = re.compile(r"Conflicting lock is held in (.+?) \(PID (\d+)\)")


def _lock_hit(text: str) -> str:
    """回被佔住的庫檔名;不是鎖撞就回空字串。"""
    t = text or ""
    if _LOCK_PHRASE not in t:
        return ""
    m = _LOCK_DB.search(t[t.index(_LOCK_PHRASE):])
    return m.group(1) if m else ""


def _lock_holder(text: str) -> str:
    m = _LOCK_PID.search(text or "")
    return f"{m.group(1)} PID {m.group(2)}" if m else ""


_DBS = re.compile(r'["\'](?:[^"\']*/)?([A-Za-z0-9_\-]+\.duckdb)["\']')
_DBCACHE: dict = {}
_DBLOCKS: dict = {}          # 庫檔名 → threading.Lock,**撞過才建**
_DBLOCKS_GUARD = threading.Lock()


def _station_dbs(b) -> set:
    """這一站的引擎原始碼裡**字面寫出**的 .duckdb 檔名。

    誠實界線:只看得到寫在這一支檔裡的名字。經模組鏈間接開的庫看不到 ——
    所以這條路只**減少**撞鎖,不宣稱消滅它;第二段序跑複判照舊留著當網子。
    """
    key = b.get("path")
    if key in _DBCACHE:
        return _DBCACHE[key]
    txt = b.get("pycode", "") if key == "PYCODE" else ""
    if key and key != "PYCODE":
        try:
            txt = Path(key).read_text(encoding="utf-8", errors="replace")
        except Exception:
            txt = ""
    out = set(_DBS.findall(txt))
    _DBCACHE[key] = out
    return out


def _learn_lock(db: str):
    """撞過的庫才建鎖 —— 不列清單(手寫清單會隨樹長大變假,LL363)。"""
    if not db:
        return
    with _DBLOCKS_GUARD:
        _DBLOCKS.setdefault(db, threading.Lock())


def _held_for(b):
    """這一站要先拿哪幾把鎖。**固定照字母序**拿 —— 一致的取鎖次序就不會成環(避免死結)。"""
    with _DBLOCKS_GUARD:
        want = sorted(_DBLOCKS[d] for d in _station_dbs(b) if d in _DBLOCKS) if _DBLOCKS else []
    return want


def _n_timeout(results) -> int:
    return sum(1 for r in results if r and r["state"] == "TIMEOUT")


def _tally(results):
    return (sum(1 for r in results if r and r["state"] == "OK"),
            sum(1 for r in results if r and r["state"] == "FAIL"),
            sum(1 for r in results if r and r["state"] == "SKIP"))


def _grid_env() -> dict:
    """批482:站的子行程環境——啟動層注入(第六個啟動器)+ ENG051 自測根改指產出夾。"""
    env = {**os.environ, "PYTHONUTF8": "1", "PYTHONWARNINGS": "ignore"}
    boot = VIA / "supportive modules" / "bootstrap"
    if boot.is_dir():
        prev = env.get("PYTHONPATH", "")
        env["PYTHONPATH"] = str(boot) + (os.pathsep + prev if prev else "")
    env["VIA_ROOT"] = str(VIA)
    # 批668:站型子行程的唯一「我在格子裡面」標記。讀格子存證的自指站靠它分辨
    #   「我讀到的是上一輪」——結構上看不到本輪的東西,不該給它一盞燈。
    env["VIA_IN_GRID"] = "1"
    env.setdefault("VIA_ACTIVE_TW_ETF_ROOT", str(VIA / "VIA_Reports" / "selftest_grid" / "active_tw_etf"))
    return env


def _why_lines(alll: list, rc: int, n_ok: int = 2) -> list:
    """批603 L81/LL160:紅的時候,摘要不能只給最後 N 行。

    自測的最後兩行常常是「最後一檢(綠)+ 計數行」,**真正紅的那一檢在上面**。
    這一輪就是活證據:格子把 MDL149 的紅站摘成「[OK] ㉒ … / [計] 二十二檢 OK 21 · FAIL 1」,
    看的人(包括我自己)得重跑一次引擎才知道紅的是 ⑬。
    紅的時候先取 `[FAIL]` 那幾行再補一行計數;都挑不到(整支是 Traceback)才退回最後兩行。
    """
    if rc == 0:
        return alll[-n_ok:]
    # 批611(尺太寬第三次):`[FAIL-CLOSED]` 是**狀態名**,不是判決行。
    # 工作站實錄:「擷取單引擎八檢」紅了,格子只印
    #   `[FAIL-CLOSED] VIA_NET_CONSENT≠YES:同意閘未開,零外呼(絕不代設)`
    # ——那一行其實是某一檢**通過時**印的誠實訊息(容器同一支 rc=0 十檢全過),
    # 真正紅的那一檢被它擠掉了,看的人拿不到任何可查的線索。
    # 挑理由的尺,挑到的必須是**判決**;狀態名長得再像也不是。
    _STATE_NOT_VERDICT = ("[FAIL-CLOSED", "[FAIL_CLOSED", "[FAILCLOSED", "[FAIL-SAFE")

    def _is_verdict_fail(l: str) -> bool:
        t = l.lstrip()
        if t.startswith(_STATE_NOT_VERDICT):
            return False
        return t.startswith(("[FAIL", "[RED", "[錯", "FAIL"))

    bad = [l for l in alll if _is_verdict_fail(l)]
    tally = [l for l in alll[-3:] if "FAIL" in l and ("計" in l or "檢" in l) and l not in bad]
    picked = bad[:2] + tally[:1]
    if not bad and tally:
        # 一行判決都挑不到(整支可能是 Traceback,或紅在計數行):把計數行擺前面,
        # 並講白「挑不到逐檢判決」,不要讓人以為畫面上這行就是原因。
        picked = ["(挑不到逐檢判決行;以下為計數與尾段)"] + tally[:1] + alll[-2:]
    return picked or alll[-2:]


def _show(r) -> str:
    """批567「自測時測字完成」:主控台印註記——敗站全文,其餘維持 96 字(一行一站才讀得動)。"""
    s = r.get("note", "") or ""
    return s if r.get("state") == "FAIL" else s[:96]


#: 批660b:格子的 run_one 固定用 sys.executable,所以跑 node 的站要用 PYCODE 包一層。
#:   這段只做三件事:找得到就跑、找不到就誠實說找不到、跑敗就照實回非 0。
_UX_PYCODE = r"""
import os, shutil, subprocess, sys
from pathlib import Path
via = Path.cwd()
t = via / "supportive modules" / "registry" / "tests" / "uxtest_master_control_v0101.js"
node = shutil.which("node")
if not node or not t.is_file():
    print("[NODATA] node 或 uxtest 檔不在——這台沒有跑它的條件,不是紅燈")
    sys.exit(2)
env = dict(os.environ)
for cand in ("/opt/node22/lib/node_modules", str(via.parent / "node_modules"), str(via / "node_modules")):
    if Path(cand).is_dir():
        env["NODE_PATH"] = cand
        break
probe = subprocess.run([node, "-e", "require('playwright')"], capture_output=True, text=True,
                       env=env, cwd=str(t.parent))
if probe.returncode != 0:
    print("[NODATA] node 在但 playwright 模組不在(npm i playwright 是操作員的手)——不是紅燈")
    sys.exit(2)
r = subprocess.run([node, str(t)], capture_output=True, text=True, env=env,
                   cwd=str(t.parent), timeout=840)
lines = [l for l in (r.stdout + r.stderr).strip().splitlines() if l.strip()]
print("\n".join(lines[-6:]) if lines else "(無輸出)")
sys.exit(0 if r.returncode == 0 else 1)
"""


_MODNF = re.compile(r"No module named '([A-Za-z0-9_.]+)'")   # 有沒有 ModuleNotFoundError: 前綴都認(有的引擎只印後半句)
_LOCAL_MODS: set | None = None


def _local_modules() -> set:
    """VIA 樹上自家模組名(.py 檔名與套件夾名),算一次。缺的名字在這裡=自家件炸了(FAIL),不在=第三方套件不在本境(SKIP)。
    尺=CGC_MDL124.tracked_set()(橋掃器的受管檔集;抄到函式才算出處 LL316,本站不另掃樹);橋掃器缺就退空集並在註記講明。"""
    global _LOCAL_MODS
    if _LOCAL_MODS is None:
        mods = set()
        try:
            import importlib.util as _ilu
            sw = sorted(HERE.glob("CGC_MDL124_BridgeSweeper_v????.py"))[-1]
            spec = _ilu.spec_from_file_location("grid_sweeper_ruler", sw)
            mod = _ilu.module_from_spec(spec)
            sys.modules["grid_sweeper_ruler"] = mod
            spec.loader.exec_module(mod)
            for rel in mod.tracked_set():
                q = Path(str(rel))
                if q.suffix == ".py":
                    mods.add(q.stem)
                    if q.name == "__init__.py":
                        mods.add(q.parent.name)
        except Exception:
            pass
        _LOCAL_MODS = mods
    return _LOCAL_MODS


def _missing_third_party(text: str, station_dir: Path | None = None) -> list:
    """輸出裡每一個 ModuleNotFoundError 的頂層名:不是自家模組的才算「境缺」。
    自家=受管檔集裡的 .py 名,或站點自己那一夾裡的 .py 名(還沒 commit 的新件也算自家)。"""
    local = set(_local_modules())
    if station_dir is not None:
        try:
            local |= {q.stem for q in Path(station_dir).glob("*.py")}
        except Exception:
            pass
    out: list = []
    for name in _MODNF.findall(text or ""):
        top = name.split(".")[0]
        if top not in out and top not in local:
            out.append(top)
    return out


def run_one(b):
    if b["path"] is None or (b["path"] != "PYCODE" and not Path(b["path"]).exists()):
        return {"name": b["name"], "state": "SKIP", "note": "引擎缺/自指佔位(誠實)", "secs": 0}
    t0 = time.time()
    try:
        if b["path"] == "PYCODE":  # pycode 站型:標準庫內聯檢(零外部檔)
            argv = [sys.executable, "-c", b["pycode"]]
            cwd = str(VIA)
        else:
            argv = [sys.executable, str(b["path"]), *b["args"]]
            cwd = str(Path(b["path"]).parent)
        r = subprocess.run(argv, capture_output=True,
                           text=True, timeout=scaled_timeout(b["timeout"]), stdin=subprocess.DEVNULL,
                           cwd=cwd, env=_grid_env())
        secs = round(time.time() - t0, 1)
        _alll = [l for l in (r.stdout + r.stderr).strip().splitlines() if l.strip()]
        tail = _why_lines(_alll, r.returncode)
        if b["expect"] == "rc0":
            state = "OK" if r.returncode == 0 else "FAIL"
        elif b["expect"] in ("doc", "nodata_ok"):
            # 批538:rc=2 是誠實 NODATA(四態律 0 綠/1 紅/2 NODATA/3 ABSENT),不是紅燈
            state = "OK" if r.returncode in (0, 2) else "FAIL"
        elif b["expect"] == "gated_ok":
            # 批663:rc=4 是 GATED——料齊、判斷做完了、剩下那一步的裁定權不在 AI 手上。
            # 算成紅等於逼自己去填一個該由操作員填的空,填下去就是發明同義字(LL90)。
            state = "OK" if r.returncode in (0, 4) else "FAIL"
        else:  # env
            state = "OK" if r.returncode == 0 else "SKIP"
        # 側線 2026-09-21 c:缺件≠壞掉。站敗但輸出說的是「第三方套件不在本境」或引擎自報 rc=3(四態律 ABSENT),
        # 判 SKIP 環境缺件(不是綠、不進分母 L57;批686 ModuleNotFoundError → ABSENT 具名套件同律)。缺的是自家模組照舊 FAIL。
        if state == "FAIL" and b["expect"] != "env":
            _miss = _missing_third_party(r.stdout + r.stderr, None if b["path"] == "PYCODE" else Path(b["path"]).parent)
            if _miss or r.returncode == 3:
                state = "SKIP"
                tail = [("套件不在本境:" + " · ".join(_miss)) if _miss else "引擎自報 ABSENT(rc=3;缺件≠壞掉)"] + list(tail)
        # 批700:庫被別人佔著 ≠ 引擎壞了。DuckDB 是單寫者,撞鎖時這一跑**量不到**。
        #   判成 FAIL 就是一盞判錯的紅燈,而判錯的紅燈跟假綠一樣傷:
        #   它會讓人去修一支根本沒壞的引擎。另立 LOCKED,既不綠也不紅。
        _db = "" if b["expect"] == "env" else _lock_hit(r.stdout + r.stderr)
        if state == "FAIL" and _db:
            state = "LOCKED"
            _learn_lock(_db)                 # 撞過才建鎖:下一站起同庫排隊,不列手寫清單
            _who = _lock_holder(r.stdout + r.stderr)
            tail = [f"庫被佔住:{_db}" + (f"(持鎖者 {_who})" if _who else "") +
                    " —— 單寫者鎖,這一跑量不到,不是引擎壞了"] + list(tail)
        # 批567「自測時測字完成」:敗站的註記是唯一線索,一律不截斷;OK/SKIP 的是計數,切了沒損失
        note = " / ".join(tail) if state in ("FAIL", "LOCKED") else " / ".join(t[:80] for t in tail)
        if state == "SKIP":
            note = "環境缺件(誠實):" + note
        return {"name": b["name"], "state": state, "rc": r.returncode, "secs": secs, "note": note}
    except subprocess.TimeoutExpired:
        # 批616:**不是紅**。逾時的站沒有結論——可能綠可能紅,我們不知道;
        # 算成紅等於編造一個沒量到的結論,還會把真紅淹掉。
        _f, _w = machine_factor()
        return {"name": b["name"], "state": "TIMEOUT", "rc": "TIMEOUT",
                "secs": b.get("timeout"), "factor": _f,
                "note": f"逾時 {b.get('timeout')}s(已按機器係數 ×{_f} 放寬;{_w})"
                        "——**沒跑完 = 沒有結論**,不是紅燈"}
    except Exception as exc:
        # 這條路必定是 FAIL:例外全文照給(批550 三次猜錯根因,就是敗在這裡被切到 60 字)
        return {"name": b["name"], "state": "FAIL", "rc": type(exc).__name__, "secs": 0, "note": str(exc)}


def _detail(b, max_lines: int = 40) -> str:
    """批347:單站全原因(重跑一次;印 [FAIL]/Traceback/Error/例外 行+末 6 行;上限 max_lines)"""
    if b["path"] is None or (b["path"] != "PYCODE" and not Path(b["path"]).exists()):
        return "(引擎缺/佔位)"
    argv = [sys.executable, "-c", b["pycode"]] if b["path"] == "PYCODE" else [sys.executable, str(b["path"]), *b["args"]]
    cwd = str(VIA) if b["path"] == "PYCODE" else str(Path(b["path"]).parent)
    try:
        r = subprocess.run(argv, capture_output=True, text=True, timeout=scaled_timeout(b["timeout"]), stdin=subprocess.DEVNULL, cwd=cwd,
                           env=_grid_env())
        lines = [l for l in (r.stdout + r.stderr).splitlines() if l.strip()]
    except subprocess.TimeoutExpired:
        return f"逾時 {b['timeout']}s"
    except Exception as exc:
        return f"{type(exc).__name__}: {exc}"
    key = [l for l in lines if ("[FAIL" in l or "Traceback" in l or "Error" in l or "錯誤" in l or "計]" in l)]
    tail = lines[-6:]
    seen, out = set(), []
    for l in key + tail:
        if l not in seen:
            seen.add(l)
            out.append(l[:220])
    return "\n".join(out[:max_lines]) + (f"\n… 共 {len(lines)} 行" if len(lines) > max_lines else "")


def _refail_targets(a: list) -> tuple:
    """--refail [json]:讀 GRID 存證取 FAIL 站名;--only a,b:子字串"""
    names = set()
    if "--refail" in a:
        i = a.index("--refail")
        p = Path(a[i + 1]) if i + 1 < len(a) and not a[i + 1].startswith("--") else None
        if p is None:
            hits = sorted(OUT.glob("GRID_*.json"))
            p = hits[-1] if hits else None
        if p and p.exists():
            d = json.loads(p.read_text(encoding="utf-8"))
            names |= {r["name"] for r in d.get("results", []) if r.get("state") == "FAIL"}
            print(f"  [refail] 來源 {p.name} · 紅站 {len(names)}")
        else:
            print("  [refail] 無 GRID 存證(先跑 via-selftest)")
    subs = []
    if "--only" in a:
        subs = [x for x in a[a.index("--only") + 1].split(",") if x]
    return names, subs


def selftest() -> int:
    """批700:**格子自己也得被量**。

    這支檔判了 293 站的生死,而它自己從來沒有一條檢。LL362 剛說「一把尺自己要在
    它量的範圍裡」—— 尺量不到自己的那個洞,不會有任何一盞燈照出來,因為照燈的那支
    也在洞外面。本批立的五檢就是把尺放進自己的範圍。

    五檢一律**實跑**,不讀原始碼複述宣告(LL354/LL358):合成站真的被跑、
    真的逾時、真的吐鎖訊息、真的計時比對重疊。
    """
    fails, n = [], [0]

    def chk(label, ok, detail=""):
        n[0] += 1
        print(f"  [{'OK' if ok else 'FAIL'}] {label} {detail}")
        if not ok:
            fails.append(label)

    # ① 態→記號只有一張表,蓋住引擎生得出的每一態,而且**永不丟例外**
    #    (舊版三處字面 dict 只寫 OK/FAIL/SKIP;TIMEOUT 一到就 KeyError)
    _states = {"OK", "FAIL", "SKIP", "TIMEOUT", "NOT_RUN", "LOCKED"}
    _src = Path(__file__).read_text(encoding="utf-8")
    # LL133 自指:第一版把舊字面表整串寫成 needle,於是它在原始碼裡**找到了自己**,
    #   ① 永遠紅。批695/697 各踩過一次,這是第三次。修法照舊:讓尺看不到自己 ——
    #   needle 由狀態資料在執行期拼出來,規則一個字都沒放寬。
    _needle = "{" + ", ".join('"%s": "%s"' % kv for kv in (("OK", "OK  "), ("FAIL", "FAIL"), ("SKIP", "SKIP"))) + "}["
    _literal = _src.count(_needle)
    try:
        _unknown = _mark("這個態沒人見過")
        _raised = False
    except Exception:
        _unknown, _raised = "", True
    chk("① 態→記號**一張表**,蓋住引擎生得出的每一態,沒見過的態要大聲現形而不是丟例外。"
        "**反面控制**:餵一個沒見過的態,舊寫法當場 KeyError(實測:有加速器時被工人吞掉、"
        "那一站的行整個不印;沒加速器時整跑炸掉),新寫法要回得出一個看得見的記號",
        _states <= set(MARKS) and not _raised and _unknown.startswith("?") and _literal == 0,
        f"(表 {sorted(MARKS)} · 沒見過的態回 {_unknown!r} · 丟例外 {_raised} · 殘留字面表 {_literal})")

    # ② 實跑:一站必定逾時,那一行**印得出來**,而且整跑不炸(兩條路都走)
    import io as _io
    import contextlib as _ctx
    import builtins as _bi
    import tempfile as _tf
    _bat, _to = battery, scaled_timeout
    _out = {}
    # 自審實錄(批700,本批自己踩的):② 第一版直接呼叫 main(),於是那兩跑**各寫了一份
    #   真的 GRID_<ts>.json 進 VIA_Reports/selftest_runs/**。而下游(VRN_ENG068 / CGC_MDL131 /
    #   CGC_MDL095 / Invoke-VIA-FinishLine)一律取**最新的** GRID_*.json 當證據 ——
    #   等於我的自測偽造了一份「全樹只有 1 站」的證據給全系統讀。
    #   同一跑裡「測試結果總表六檢」與「三軌測試矩陣自測」當場紅給我看(站數>100 不成立)。
    #   **一把尺放進自己的範圍量自己,不可以在量的過程中改變被量的東西。**
    #   修法:合成跑的產出全部改道到拋棄式暫存夾;跑完驗真夾裡**一份都沒多**。
    _real_out, _real_prog = OUT, PROG_P
    _before = sorted(q.name for q in _real_out.glob("GRID_*.json")) if _real_out.exists() else []
    _tmp = Path(_tf.mkdtemp(prefix="gridselftest_"))
    for _mode in ("accel", "noaccel"):
        _buf = _io.StringIO()
        _realimp = _bi.__import__

        def _blocked(name, *aa, **kk):
            if name == "VIA_SuperAccel_Module":
                raise ImportError("自測:合成的加速器缺席")
            return _realimp(name, *aa, **kk)
        globals()["OUT"] = _tmp                      # 合成跑零足跡:不碰真的證據夾
        globals()["PROG_P"] = _tmp / "SELFTEST_PROGRESS.json"
        globals()["battery"] = lambda fast: [{"name": "自測合成:必定逾時站", "path": "PYCODE",
                                              "args": [], "expect": "rc0", "timeout": 1,
                                              "pycode": "import time; time.sleep(9)"}]
        globals()["scaled_timeout"] = lambda sec: 1
        _sv = sys.argv[:]
        sys.argv = ["grid"]
        if _mode == "noaccel":
            _bi.__import__ = _blocked
        try:
            with _ctx.redirect_stdout(_buf):
                _rc = main()
            _out[_mode] = (_rc, _buf.getvalue())
        except Exception as _e:
            _out[_mode] = (f"炸了:{type(_e).__name__}:{_e}", _buf.getvalue())
        finally:
            _bi.__import__ = _realimp
            sys.argv = _sv
            globals()["battery"], globals()["scaled_timeout"] = _bat, _to
            globals()["OUT"], globals()["PROG_P"] = _real_out, _real_prog
    _after = sorted(q.name for q in _real_out.glob("GRID_*.json")) if _real_out.exists() else []
    _footprint = [x for x in _after if x not in _before]
    _syn = sorted(q.name for q in _tmp.glob("GRID_*.json"))
    _ok2 = all(_out[m][0] == 2 and "自測合成:必定逾時站" in _out[m][1]
               and "[TIME]" in _out[m][1] for m in ("accel", "noaccel")) and not _footprint and len(_syn) == 2
    import shutil as _sh
    _sh.rmtree(_tmp, ignore_errors=True)
    chk("② 實跑一站必定逾時:**兩條路**(加速器在位 accel_map / 缺席 ThreadPoolExecutor 退路)"
        "都要印得出那一站、rc 都要是 2(逾時=沒量完,不冒充全綠)、都不准炸。"
        "這一檢就是 LL354:分支存在不等於分支被走到,所以逼它真的逾時一次。"
        "**而且零足跡**:合成跑的 GRID_*.json 一律落在拋棄式暫存夾,真證據夾一份都不准多——"
        "本批第一版沒做這件事,那兩跑各寫了一份「全樹只有 1 站」的證據進真夾,"
        "下游一律取最新的 GRID_*.json,等於我的自測偽造證據給全系統讀"
        "(同一跑裡『測試結果總表六檢』與『三軌測試矩陣自測』當場紅給我看)。"
        "**尺放進自己的範圍量自己,不可以在量的過程中改變被量的東西**",
        _ok2,
        f"(accel rc={_out['accel'][0]} · noaccel rc={_out['noaccel'][0]}"
        f" · 印得出站名 {[('自測合成:必定逾時站' in _out[m][1]) for m in ('accel', 'noaccel')]}"
        f" · 真證據夾多出來的檔 {_footprint or '無'}(必須無)· 合成證據落在暫存夾 {len(_syn)} 份)")

    # ③ 鎖撞判準寫得窄:要同時有 DuckDB 那句鎖訊息**和**一個 .duckdb 檔名
    _real = ('_duckdb.IOException: IO Error: Could not set lock on file '
             '"/x/y/vdf_tw_market.duckdb": Conflicting lock is held in /usr/bin/python3.11 (PID 19568).')
    _fake_a = "AssertionError: duckdb 表列數不符 · vdf_tw_market.duckdb 內容不對"
    _fake_b = "OSError: could not set lock on file /tmp/a.txt"
    chk("③ 鎖撞判準**窄**:要同時有 DuckDB 那句鎖訊息和一個 .duckdb 檔名才算。"
        "**反面控制**:真的壞掉但文字裡提到 duckdb 的、以及鎖的是別種檔的,一律不得被當成鎖撞——"
        "判寬一點就變成一道把紅洗成非紅的後門,那比假紅更糟(假紅有人去查,假綠沒有)",
        _lock_hit(_real) == "vdf_tw_market.duckdb" and not _lock_hit(_fake_a) and not _lock_hit(_fake_b)
        and "PID 19568" in _lock_holder(_real),
        f"(真 {_lock_hit(_real)!r} · 持鎖者 {_lock_holder(_real)!r} · 假一 {_lock_hit(_fake_a)!r} · 假二 {_lock_hit(_fake_b)!r})")

    # ④ 實跑:吐鎖訊息的站判 LOCKED、普通壞掉的站判 FAIL(同樣 rc=1,分得出來才算)
    _lk = run_one({"name": "自測合成:鎖撞站", "path": "PYCODE", "args": [], "expect": "rc0", "timeout": 30,
                   "pycode": ("import sys;sys.stderr.write('_duckdb.IOException: IO Error: Could not set "
                              "lock on file \"/x/vdf_tw_market.duckdb\": Conflicting lock is held in "
                              "/usr/bin/python3 (PID 4242).');sys.exit(1)")})
    _rd = run_one({"name": "自測合成:真壞站", "path": "PYCODE", "args": [], "expect": "rc0", "timeout": 30,
                   "pycode": "import sys;sys.stderr.write('AssertionError: 真的壞了');sys.exit(1)"})
    chk("④ 實跑分得出鎖撞與真壞:兩站**同樣 rc=1**,吐鎖訊息的要判 LOCKED(既不綠也不紅)、"
        "普通壞掉的要判 FAIL。rc 一樣而判定不同——分不出來就會有一盞判錯的紅燈,"
        "而判錯的紅燈會讓人去修一支沒壞的引擎",
        _lk["state"] == "LOCKED" and _rd["state"] == "FAIL" and "vdf_tw_market.duckdb" in _lk["note"]
        and "PID 4242" in _lk["note"],
        f"(鎖撞站 {_lk['state']} rc{_lk['rc']} · 真壞站 {_rd['state']} rc{_rd['rc']})")

    # ⑤ 實跑:同庫兩工**時間不重疊**、異庫兩工**會重疊**
    from concurrent.futures import ThreadPoolExecutor as _TPE
    def _span(dbs_a, dbs_b):
        _sv = dict(_DBLOCKS)
        _DBLOCKS.clear()
        for d in set(dbs_a) | set(dbs_b):
            _learn_lock(d)
        marks = {}
        def _work(tag_dbs):
            tag, dbs = tag_dbs
            b = {"path": f"SYN::{tag}", "name": tag}
            _DBCACHE[b["path"]] = set(dbs)
            held = _held_for(b)
            for lk in held:
                lk.acquire()
            try:
                t0 = time.perf_counter(); time.sleep(0.25); marks[tag] = (t0, time.perf_counter())
            finally:
                for lk in reversed(held):
                    lk.release()
        with _TPE(max_workers=2) as ex:
            list(ex.map(_work, [("A", dbs_a), ("B", dbs_b)]))
        _DBLOCKS.clear(); _DBLOCKS.update(_sv)
        (a0, a1), (b0, b1) = marks["A"], marks["B"]
        return min(a1, b1) - max(a0, b0) > 0        # 重疊為正
    _same = _span(["same.duckdb"], ["same.duckdb"])
    _diff = _span(["one.duckdb"], ["two.duckdb"])
    chk("⑤ 實跑排隊真的排到:同庫兩工**時間區間不重疊**、異庫兩工**會重疊**(量的是時鐘不是程式碼)。"
        "**反面控制**就是異庫那一組——只證明「同庫不重疊」還不夠,那把 workers 設成 1 也會過,"
        "要同時證明它**沒有把整個平行度賠掉**",
        (not _same) and _diff, f"(同庫重疊 {_same}(必須 False)· 異庫重疊 {_diff}(必須 True))")

    # ── 批704 ⑥:站覆蓋率自己也要有一把尺 ──────────────────────────────────
    _cov = station_coverage()
    if _cov["state"] != "OK":
        chk("⑥ 站覆蓋率(受治理家族有沒有人看)", False, "NODATA · " + _cov["why"])
    else:
        _nowhy = [r["family"] for r in _cov["rows"] if r["state"] == "EXEMPT" and not r["why"]]
        _self_in = [r["family"] for r in _cov["rows"] if r["family"] == _SELF_FAMILY]
        # 下限:批704 補進來的每一支都必須還在站面上(換版只准多不准少)。
        #   批705 自審:v0457 這裡寫的是**一份手寫的五個名字**——
        #   我前一批才剛重述 LL363「手寫的掃描清單是會過期的斷言」,下一批自己就寫了一份。
        #   改成**從站表自己算**:站名帶「批704」的那些站,它們的家族就是下限。
        _b704 = {re.sub(r"_v\d{1,4}\.py$", "", Path(s["path"]).name).removesuffix(".py")
                 for s in battery(False) if s.get("path") and "批704" in s["name"]}
        _lost = sorted(_b704 - {r["family"] for r in _cov["rows"] if r["state"] == "STATIONED"})
        # 反面控制:餵一份**只有一站**的假站表,覆蓋率必須當場崩、PENDING 必須暴增。
        _poison = station_coverage(stations=[{"path": "CGC_MDL064_SelftestGrid_v0457.py"}])
        _bit = _poison["state"] == "OK" and _poison["tally"]["PENDING"] > _cov["tally"]["PENDING"]
        # 批705 自審:第一版這一檢是綠的,而可跑性整片回 UNREADABLE(`ast` 沒 import,
        #   NameError 被 except Exception 吞成 UNREADABLE)。**分類器整支壞掉,檢照樣綠**——
        #   因為沒有一條斷言在看它。附帶的欄位也要有人看,不然它就是裝飾。
        _pk = _cov.get("pending_kind") or {}
        _cls_ok = (not _cov["pending"]) or (
            set(_pk) - {"UNREADABLE", "UNPARSED"} != set()
            and _probe_kind('import argparse\nargparse.ArgumentParser().add_argument("--selftest")\n')
            == "SELFTEST"
            and _probe_kind('if __name__ == "__main__":\n    pass\n') == "MAIN_ONLY")
        chk("⑥ 站覆蓋率:受治理家族逐支三態(有站/具名豁免/還沒人看),豁免要寫得出為什麼、"
            "還沒人看的要**逐支指名**;**LL133** 格子自己不進自己的分母;"
            "**反面控制**=餵一份只有一站的假站表,覆蓋率必須當場崩",
            not _nowhy and not _self_in and not _lost and _bit and _cls_ok,
            f"({_cov['pct']}% · 有站 {_cov['tally']['STATIONED']} · 豁免 {_cov['tally']['EXEMPT']}"
            f" · 還沒人看 {_cov['tally']['PENDING']} · 無 why {_nowhy or '無'}"
            f" · 自己進分母 {_self_in or '無'} · 下限 {len(_b704)} 掉了 {_lost or '無'}"
            f" · 還沒人看的可跑性 {_cov.get('pending_kind')} · 分類器活著 {_cls_ok}"
            f" · 負控咬住 {_bit})")

    # 批704(LL372):檢數不寫死,由 chk 自己數。
    print(f"  [計] {n[0]} 檢 OK {n[0] - len(fails)} · FAIL {len(fails)}")
    return 1 if fails else 0


def main() -> int:
    a = sys.argv[1:]
    fast = "--fast" in a
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    B = battery(fast)
    if "--refail" in a or "--only" in a:  # 批347:逐站除錯模式
        names, subs = _refail_targets(a)
        max_lines = int(a[a.index("--lines") + 1]) if "--lines" in a and a.index("--lines") + 1 < len(a) else 40
        sel = [b for b in B if b["name"] in names or any(sb in b["name"] for sb in subs)]
        print(f"=== 逐站除錯(v0265)· {len(sel)} 站 · 全原因 ===")
        results = []
        for b in sel:
            r = run_one(b)
            r["detail"] = _detail(b, max_lines) if r["state"] == "FAIL" else ""
            results.append(r)
            mark = _mark(r["state"])
            print(f"  [{mark}] {r['name']} · {r['secs']}s")
            if r["detail"]:
                for l in r["detail"].splitlines():
                    print("      | " + l)
        n_ok = sum(1 for r in results if r["state"] == "OK")
        n_fail = sum(1 for r in results if r["state"] == "FAIL")
        OUT.mkdir(parents=True, exist_ok=True)
        ev = OUT / f"REFAIL_{ts}.json"
        ev.write_text(json.dumps({"schema": "VIA.SelftestGrid.refail.v1", "ts": ts, "n": len(sel), "ok": n_ok, "fail": n_fail,
                                  "results": results}, ensure_ascii=False, indent=1), encoding="utf-8")
        print(f"  [計] 重跑 {len(sel)} 站 · OK {n_ok} · FAIL {n_fail}(轉綠 {n_ok})· 存證 {ev.name}")
        return 0 if n_fail == 0 else 1
    print(f"=== 全面自測矩陣 v0265 · {len(B)} 站 · {'FAST' if fast else 'FULL'} · 全安全模式(零 commit 零網路)===")
    print(f"  [{accel_lamp()}]", flush=True)          # 批423:20 加速器真點名(缺席誠實說缺)
    results = [None] * len(B)
    workers = 1 if "--serial" in a else max(1, int(os.environ.get("VIA_GRID_WORKERS") or min(8, os.cpu_count() or 4)))
    t_grid = time.time()
    done_n = [0]
    print(f"  [進度] 動態進度條{'(TTY 就地重畫)' if _TTY else '(非 TTY:每 10 站一行)'}"
          f" · 心跳 {PROG_P.name}(每站落檔;外部可證明還活著)· Ctrl+C 安全落檔", flush=True)
    _progress_write(0, len(B), t_grid, 0, 0, 0, "啟動", "RUNNING")

    def _job(ib):
        i, b = ib
        # 批700:撞過的庫才排隊(_DBLOCKS 撞過才長)。沒撞過=零成本,撞過一次之後同庫的站互相讓。
        #   照字母序拿鎖 —— 一致的取鎖次序不會成環,所以不會死結。
        held = _held_for(b)
        for lk in held:
            lk.acquire()
        try:
            r = run_one(b)
        finally:
            for lk in reversed(held):
                lk.release()
        results[i] = r
        done_n[0] += 1
        mark = _mark(r["state"])
        if _TTY:
            print("\r" + " " * 78 + "\r", end="")     # 清掉進度條那一行再印站名
        print(f"  [{mark}] {r['name']} · {r['secs']}s · {_show(r)}"
              + (f"  ({done_n[0]}/{len(B)} · {int(time.time() - t_grid)}s)" if workers > 1 else ""), flush=True)
        try:
            _ok, _fa, _sk = _tally(results)
            _bar(done_n[0], len(B), t_grid, _ok, _fa, _sk, b["name"])
            _progress_write(done_n[0], len(B), t_grid, _ok, _fa, _sk, b["name"], "RUNNING")
        except Exception as _e:      # 批700:進度條/心跳壞掉不可以連帶讓那一站消失,也不可以殺掉整跑
            print(f"  [註] 進度條/心跳寫入失敗({type(_e).__name__}),站的結果已記下;整跑續行", flush=True)
        return True

    interrupted = False
    try:
      if workers > 1:
        print(f"  [平行] 工人 {workers}(SUP_MDL737 accel_map;--serial 退原序)", flush=True)
        try:
            import VIA_SuperAccel_Module as _A
            _A.accel_map(_job, list(enumerate(B)), workers=workers)
        except KeyboardInterrupt:
            raise
        except Exception:
            from concurrent.futures import ThreadPoolExecutor
            with ThreadPoolExecutor(max_workers=workers) as ex:
                list(ex.map(_job, list(enumerate(B))))
        results = [r if r else {"name": b["name"], "state": "FAIL", "rc": "NORESULT", "secs": 0, "note": "平行工人無回(誠實)"} for r, b in zip(results, B)]
        # 第二段(讓庫律):平行敗站序跑一次=排除 duckdb 單寫者鎖/產物半寫之假紅;終態取序跑;note 留「平行敗→序跑」
        #   批700:LOCKED 也要複判 —— 它本來就是「這一跑量不到」,序跑正是它該有的第二次機會。
        #   而複判之後**仍然撞鎖就維持 LOCKED,絕不改判紅**:那多半是機外的行程佔著庫
        #   (工作站上 VDF 管線在跑就會這樣),把它寫成紅燈等於叫人去修一支沒壞的引擎。
        redo = [i for i, r in enumerate(results) if r["state"] in ("FAIL", "LOCKED")]
        n_lock1 = sum(1 for r in results if r["state"] == "LOCKED")
        if redo:
            print(f"  [第二段] 平行敗 {len(redo)} 站→序跑複判(讓庫律;其中鎖撞 {n_lock1} 站)", flush=True)
            for i in redo:
                _was = results[i]["state"]
                r2 = run_one(B[i])
                _head = ("鎖撞→序跑 " if _was == "LOCKED" else "平行敗→序跑 ") + {
                    "OK": "轉綠", "LOCKED": "仍被佔(不是紅)", "SKIP": "轉缺件", "TIMEOUT": "逾時"
                }.get(r2["state"], "仍紅") + ":"
                r2["note"] = _head + r2.get("note", "")
                results[i] = r2
                mark = _mark(r2["state"])
                print(f"  [{mark}] {r2['name']} · {r2['secs']}s · {_show(r2)}", flush=True)
      else:
        for i, b in enumerate(B):
            _job((i, b))
    except KeyboardInterrupt:
        # 批423:中斷不是崩潰。已跑完的站是真證據,寫出來再走;
        # 沒跑到的誠實標 NOT_RUN,不拿空白冒充 SKIP。
        interrupted = True
        if _TTY:
            print()
        print(f"\n  [中斷] Ctrl+C —— 已完成 {done_n[0]}/{len(B)} 站,"
              f"落檔已完成部分(未跑到的標 NOT_RUN,不冒充 SKIP)", flush=True)
    results = [r if r else {"name": b["name"], "state": "NOT_RUN", "rc": "INTERRUPTED" if interrupted else "NORESULT",
                            "secs": 0, "note": "中斷時尚未跑到(誠實)" if interrupted else "無回(誠實)"}
               for r, b in zip(results, B)]
    n_ok, n_fail, n_skip = _tally(results)
    n_nr = sum(1 for r in results if r["state"] == "NOT_RUN")
    n_lock = sum(1 for r in results if r["state"] == "LOCKED")
    if _TTY:
        _bar(done_n[0], len(B), t_grid, n_ok, n_fail, n_skip)
        print()
    OUT.mkdir(parents=True, exist_ok=True)
    ev = OUT / f"GRID_{ts}.json"
    ev.write_text(json.dumps({"schema": "VIA.SelftestGrid.v1", "ts": ts, "fast": fast,
                              "interrupted": interrupted, "done": done_n[0], "total": len(B),
                              "ok": n_ok, "fail": n_fail, "skip": n_skip, "not_run": n_nr,
                              "timeout": _n_timeout(results), "locked": n_lock,
                              "locked_dbs": sorted(_DBLOCKS),
                              "machine_factor": machine_factor()[0],
                              "machine_factor_why": machine_factor()[1],
                              "elapsed_s": round(time.time() - t_grid, 1), "results": results},
                             ensure_ascii=False, indent=1), encoding="utf-8")
    _progress_write(done_n[0], len(B), t_grid, n_ok, n_fail, n_skip,
                    "", "INTERRUPTED" if interrupted else "DONE")
    n_to = _n_timeout(results)
    _f, _w = machine_factor()
    print(f"  [計] OK {n_ok} · FAIL {n_fail} · SKIP {n_skip} · TIMEOUT {n_to}"
          + (f" · LOCKED {n_lock}(庫被佔住,量不到)" if n_lock else "")
          + (f" · NOT_RUN {n_nr}(中斷)" if n_nr else "")
          + f"(誠實多態)· {int(time.time() - t_grid)}s · 機器係數 ×{_f}({_w})"
          + f" · 存證 {ev.name}")
    if n_lock:
        # 批700:鎖撞逐站點名。不點名就等於默默把「量不到」混進「沒問題」裡。
        print(f"  [鎖撞] {n_lock} 站序跑之後庫還是被佔著(**不是紅**,是這一跑量不到)——"
              f"多半是機外行程佔著庫;等它放開再跑,或 --serial:")
        for r in results:
            if r and r["state"] == "LOCKED":
                print(f"   · {r['name'][:60]} · {r.get('note','')[:90]}")
    if _DBLOCKS:
        print(f"  [排隊] 這一跑學到的單寫者庫 {sorted(_DBLOCKS)} —— "
              f"撞過才建鎖,同庫的站自此互相讓(只看得到引擎原始碼字面寫出的庫名,"
              f"經模組鏈間接開的看不到,所以第二段序跑複判照舊留著當網子)")
    if n_to:
        # 批616:逾時的站**沒有結論**,所以要逐站點名——不點名就等於默默當它過了
        print(f"  [逾時] {n_to} 站沒跑完(不是紅,是沒有結論;要它們有結論就給更長的逾時"
              f"或 VIA_GRID_TIME_FACTOR 調大):")
        for r in results:
            if r and r["state"] == "TIMEOUT":
                print(f"   · {r['name'][:70]} · 給了 {r.get('secs')}s×{_f}")
    if interrupted:
        return 130                              # 128+SIGINT:中斷不冒充成功也不冒充失敗
    if n_fail:
        return 1
    return 2 if n_to else 0                     # 有逾時=沒量完=誠實 NODATA,不冒充全綠


if __name__ == "__main__":
    # 批700:--selftest 擺在 main() 外面 —— ② 檢要**真的呼叫 main()** 跑一站合成逾時站,
    #   放進 main() 裡就會遞迴。尺要放進自己量的範圍(LL362),但不可以咬到自己(LL133)。
    if "--selftest" in sys.argv[1:]:
        print(f"=== 全面自測矩陣 自測(CGC_MDL064 v{Path(__file__).stem.rsplit('_v', 1)[-1]})· 五檢 · 零網路零寫庫 ===")
        sys.exit(selftest())
    sys.exit(main())
